test_exact_projection_input_preserved_and_evidence_indices[pragma solidity ^0.4.25;
contract MY_BANK {
 struct Holder { uint unlockTime; uint balance; }
 mapping(address => Holder) public Acc;
 uint public MinSum;
 function Collect(uint _am) public payable {
 var acc = Acc[msg.sender];
 if (acc.balance >= MinSum && acc.balance >= _am && now > acc.unlockTime) {
 if (msg.sender.call.value(_am)()) {
 acc.balance -= _am;
 }
 }
 }
}]

test_exact_projection_input_preserved_and_evidence_indices[pragma solidity ^0.5.0;
contract C {
 struct S { uint a; uint b; }
 uint[] data;
 function f() public returns (uint) {
 S memory s = S(1, 2);
 s.a = 3;
 uint y = s.b;
 s = S(4, 5);
 uint z = s.a;
 return y + z;
 }
 function g() public returns (uint) {
 uint[] storage arr = data;
 arr.push(1);
 uint n = arr.length;
 return n;
 }
}]

